"""Inspect/render fictional PDFs generated by verify-patient-pdfs.cjs."""
from pathlib import Path
import pymupdf

folder = Path(__file__).resolve().parents[1] / 'tmp' / 'pdfs'
for name in ['patient-summary', 'medical-records', 'long-record']:
    doc = pymupdf.open(folder / f'{name}.pdf')
    text = ''.join(page.get_text() for page in doc)
    assert '検証用 山田花子' in text, 'Patient name must survive text extraction'
    for index, page in enumerate(doc):
        assert abs(page.rect.width - 595.28) < 1 and abs(page.rect.height - 841.89) < 1
        for word in page.get_text('words'):
            assert word[0] >= 40 and word[2] <= 555, (name, index, word)
            assert word[1] >= 28 and word[3] <= 820, (name, index, word)
        page.get_pixmap(matrix=pymupdf.Matrix(1.5, 1.5)).save(folder / f'{name}-{index+1}.png')
    if name == 'patient-summary':
        assert len(doc) == 1
        assert '38歳' in text and '090-0000-0000' in text and '080-0000-0000' in text
    if name == 'medical-records':
        assert len(doc) >= 3 and '再診の記録' in text
        assert '0 本' in text and '36.5 ℃' in text
        assert 'AROM 120°' in text and '説明内容・同意の確認' in text and '次回の評価・対応予定' in text
    if name == 'long-record':
        assert text.count('長文の現症を途中で切らずに改ページできることを確認する。') == 150
        assert '現症の最終行' in text and '長文記録の最終備考' in text
    print(f'{name}: {len(doc)} A4 pages; text and margins verified')
